const express = require('express');
const { paymentGateway } = require('../gateway');
const { verifySupportAgent } = require('../auth');
const { Transaction } = require('../models');

const app = express();
app.use(express.json());

app.post('/api/copilot/tools/issue-refund', verifySupportAgent, async (req, res) => {
  const { transactionId, refundAmountDollars, reason } = req.body.toolArgs || {};

  // Verify transaction belongs to the store managed by the support agent
  const transaction = await Transaction.findOne({
    where: {
      id: transactionId,
      merchantId: req.user.merchantId
    }
  });

  if (!transaction) {
    return res.status(404).json({ error: 'Transaction not found in your merchant store' });
  }

  const refund = await paymentGateway.refundTransaction({
    transactionId: transaction.id,
    amount: refundAmountDollars,
    reason: reason || 'Customer satisfaction',
    merchantId: req.user.merchantId
  });

  res.json({ success: true, refundId: refund.id, status: refund.status });
});

app.listen(8112);
